 public interface IWindowsBrightnessGuiBackend:IDisposable {object SessionIdentity {get;}bool WritesAvailable {get;}Task<WindowsBrightnessReply> Request(Dictionary<string,object> request,object expectedSession,Action beforeSend);}
 public sealed class WindowsBrightnessWorkerBackend:IWindowsBrightnessGuiBackend {
  const string WriteQuarantineKey="OpenAC.WindowsBrightness.WriteQuarantine.v1";
  readonly WorkerClient worker;readonly Func<object> sessionIdentity;readonly Func<Dictionary<string,object>,object,Action,Task<WindowsBrightnessReply>> send;readonly Action close;volatile bool disposed;int pendingSets;
  public WindowsBrightnessWorkerBackend(){string root=AppDomain.CurrentDomain.GetData("OpenAC.PreviewWorkerRoot") as string;worker=new WorkerClient(Path.Combine(String.IsNullOrEmpty(root)?AppDomain.CurrentDomain.BaseDirectory:root,"WindowsBrightnessWorker.exe"),WindowsBrightnessRules.WorkerBudgetMilliseconds);sessionIdentity=()=>worker.SessionIdentity;send=(request,session,beforeSend)=>worker.Request<WindowsBrightnessReply>(request,session,WindowsBrightnessRules.WorkerBudgetMilliseconds,beforeSend);close=()=>worker.Dispose();}
  // The injected transport lets pure tests exercise the production quarantine
  // path without constructing a process, COM object, or WMI provider.
  public WindowsBrightnessWorkerBackend(Func<object> session,Func<Dictionary<string,object>,object,Action,Task<WindowsBrightnessReply>> transport,Action dispose){if(session==null||transport==null||dispose==null)throw new ArgumentNullException();sessionIdentity=session;send=transport;close=dispose;}
  public object SessionIdentity {get{return disposed?null:sessionIdentity();}}
  public bool WritesAvailable {get{return !disposed&&!Object.Equals(AppDomain.CurrentDomain.GetData(WriteQuarantineKey),true);}}
  public async Task<WindowsBrightnessReply> Request(Dictionary<string,object> request,object expectedSession,Action beforeSend){if(disposed)throw new ObjectDisposedException("BrightnessWorker");object raw;string op=request!=null&&request.TryGetValue("op",out raw)?raw as string:null;if(op!="read"&&op!="set")throw new WindowsBrightnessFailure("INVALID_REQUEST");if(op=="set"&&(expectedSession==null||beforeSend==null||!WritesAvailable))throw new WindowsBrightnessFailure("CONTROL_DISABLED");bool mayHaveSubmitted=false;Action terminal=()=>{if(op=="set"&&!WritesAvailable)throw new WindowsBrightnessFailure("CONTROL_UNAVAILABLE");if(beforeSend!=null)beforeSend();if(op=="set")mayHaveSubmitted=true;};if(op=="set")Interlocked.Increment(ref pendingSets);try{var reply=await send(request,expectedSession,terminal);if(op=="set"&&UnknownCompletionReply(reply))AppDomain.CurrentDomain.SetData(WriteQuarantineKey,true);return reply;}catch(TimeoutException){if(op=="set")AppDomain.CurrentDomain.SetData(WriteQuarantineKey,true);throw;}catch{if(op=="set"&&mayHaveSubmitted)AppDomain.CurrentDomain.SetData(WriteQuarantineKey,true);throw;}finally{if(op=="set")Interlocked.Decrement(ref pendingSets);}}
  static bool UnknownCompletionReply(WindowsBrightnessReply reply){object raw;if(reply==null)return true;if(reply.data!=null&&reply.data.TryGetValue("errorCode",out raw)&&WindowsBrightnessRules.UnknownMethodCompletion(raw as string))return true;var error=reply.error as Dictionary<string,object>;return error!=null&&error.TryGetValue("code",out raw)&&WindowsBrightnessRules.UnknownMethodCompletion(raw as string);}
  public void Dispose(){if(Interlocked.CompareExchange(ref pendingSets,0,0)>0)AppDomain.CurrentDomain.SetData(WriteQuarantineKey,true);disposed=true;close();}
 }
 public sealed class WindowsBrightnessFailure:Exception {public readonly string Code;public WindowsBrightnessFailure(string code):base(code){Code=code;}}
 public sealed class WindowsBrightnessMonitor {
  public string Id {get;internal set;}public string Name {get;internal set;}public string Fingerprint {get;internal set;}public string UnavailableReason {get;internal set;}
  public int? CurrentBrightness {get;internal set;}public ReadOnlyCollection<int> Levels {get;internal set;}public bool SupportsWrite {get;internal set;}
 }
 public sealed class WindowsBrightnessSnapshot {
  public ReadOnlyCollection<WindowsBrightnessMonitor> Monitors {get;internal set;}public DateTime CapturedUtc {get;internal set;}
  internal Guid Owner;internal object WorkerSession;internal string SessionToken,ReadToken;internal bool Consumed;
 }
 public sealed class WindowsBrightnessOutcome {public bool AlreadyCurrent,WriteAttempted,ReadbackConfirmed;public uint? MethodReturnCode;public int? OriginalBrightness;public string ErrorCode;public WindowsBrightnessMonitor Observed;}
 public sealed class WindowsBrightnessClient:IDisposable {
  readonly IWindowsBrightnessGuiBackend backend;readonly Func<DateTime> utc;readonly Guid owner=Guid.NewGuid();readonly SemaphoreSlim gate=new SemaphoreSlim(1,1);bool disposed;WindowsBrightnessSnapshot currentCapture;
  public WindowsBrightnessClient(IWindowsBrightnessGuiBackend source,Func<DateTime> now=null){if(source==null)throw new ArgumentNullException("source");backend=source;utc=now??(()=>DateTime.UtcNow);}
  public bool WritesAvailable {get{return !disposed&&backend.WritesAvailable;}}
  static object Value(IDictionary<string,object> map,string key){object raw;return map!=null&&map.TryGetValue(key,out raw)?raw:null;}
  static string Text(IDictionary<string,object> map,string key){return Value(map,key) as string;}
  static object[] Items(object raw){var values=raw as IEnumerable;return raw==null||raw is string||raw is IDictionary||values==null?null:values.Cast<object>().ToArray();}
  static bool? Flag(IDictionary<string,object> map,string key){object raw=Value(map,key);return raw is bool?(bool?)raw:null;}
  static int? Integer(object raw){return raw is int?(int?)raw:null;}
  static uint? ReturnCode(object raw){if(raw==null)return null;if(raw is int&&(int)raw>=0)return (uint)(int)raw;if(raw is long&&(long)raw>=0&&(long)raw<=UInt32.MaxValue)return (uint)(long)raw;if(raw is uint)return (uint)raw;throw new WindowsBrightnessFailure("INVALID_RESPONSE");}
  static WindowsBrightnessMonitor ParseMonitor(Dictionary<string,object> row){if(row==null||!WindowsBrightnessRules.TargetId(Text(row,"id"))||!WindowsBrightnessRules.HashToken(Text(row,"fingerprint"))||Flag(row,"supportsWrite")==null)throw new WindowsBrightnessFailure("INVALID_RESPONSE");string name=Text(row,"name");if(String.IsNullOrWhiteSpace(name)||name.Length>64||name.Any(Char.IsControl))throw new WindowsBrightnessFailure("INVALID_RESPONSE");object current=Value(row,"currentBrightness");if(current!=null&&(!(current is int)||(int)current<0||(int)current>100))throw new WindowsBrightnessFailure("INVALID_RESPONSE");var raw=Items(Value(row,"levels"));if(raw==null||raw.Length>101||raw.Any(v=>!(v is int)||(int)v<0||(int)v>100))throw new WindowsBrightnessFailure("INVALID_RESPONSE");var levels=raw.Cast<int>().ToArray();if(!levels.SequenceEqual(levels.Distinct().OrderBy(v=>v)))throw new WindowsBrightnessFailure("INVALID_RESPONSE");bool writable=Flag(row,"supportsWrite")==true;if(writable&&!WindowsBrightnessRules.LevelsValid(levels,levels.Length,Integer(current)))throw new WindowsBrightnessFailure("INVALID_RESPONSE");string reason=Text(row,"unavailableReason");if(writable&&reason!=null||reason!=null&&!new[]{"AMBIGUOUS_MONITOR","INVALID_LEVELS","METHOD_NOT_PAIRED"}.Contains(reason))throw new WindowsBrightnessFailure("INVALID_RESPONSE");return new WindowsBrightnessMonitor{Id=Text(row,"id"),Name=name,Fingerprint=Text(row,"fingerprint"),CurrentBrightness=Integer(current),Levels=new ReadOnlyCollection<int>(levels),SupportsWrite=writable,UnavailableReason=reason};}
  static void Successful(WindowsBrightnessReply reply){if(reply==null)throw new WindowsBrightnessFailure("INVALID_RESPONSE");if(!reply.ok){var error=reply.error as Dictionary<string,object>;string code=Text(error,"code");throw new WindowsBrightnessFailure(new[]{"INVALID_REQUEST","CAPTURE_EXPIRED","UNSUPPORTED_LEVEL","CURRENT_CHANGED","INVALID_PROVIDER_DATA","ACCESS_DENIED","WMI_PROVIDER_FAILED","QUERY_FAILED"}.Contains(code)?code:"QUERY_FAILED");}}
  public bool IsCurrent(WindowsBrightnessSnapshot snapshot){return !disposed&&snapshot!=null&&Object.ReferenceEquals(snapshot,currentCapture)&&!snapshot.Consumed&&snapshot.Owner==owner&&snapshot.WorkerSession!=null&&Object.ReferenceEquals(snapshot.WorkerSession,backend.SessionIdentity)&&WindowsBrightnessRules.Current(snapshot.CapturedUtc,utc());}
  public async Task<WindowsBrightnessSnapshot> ReadAsync(){if(disposed)throw new ObjectDisposedException("BrightnessClient");if(!await gate.WaitAsync(0))throw new WindowsBrightnessFailure("INTERFACE_BUSY");try{if(currentCapture!=null)currentCapture.Consumed=true;currentCapture=null;var reply=await backend.Request(new Dictionary<string,object>{{"op","read"}},null,()=>{if(disposed)throw new ObjectDisposedException("BrightnessClient");});Successful(reply);var data=reply.data;DateTime captured;var raw=Items(Value(data,"monitors"));if(Integer(Value(data,"schema"))!=1||!WindowsBrightnessRules.Token(Text(data,"sessionToken"))||!WindowsBrightnessRules.Token(Text(data,"readToken"))||Integer(Value(data,"expiresAfterMilliseconds"))!=WindowsBrightnessRules.LeaseMilliseconds||!DateTime.TryParseExact(Text(data,"capturedAtUtc"),"o",CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind,out captured)||captured.Kind!=DateTimeKind.Utc||!WindowsBrightnessRules.Current(captured,utc())||raw==null||raw.Length>WindowsBrightnessRules.MaximumMonitors)throw new WindowsBrightnessFailure("INVALID_RESPONSE");var monitors=raw.Select(v=>ParseMonitor(v as Dictionary<string,object>)).ToList();if(monitors.Select(m=>m.Id).Distinct(StringComparer.Ordinal).Count()!=monitors.Count)throw new WindowsBrightnessFailure("INVALID_RESPONSE");object session=backend.SessionIdentity;if(disposed||session==null)throw new WindowsBrightnessFailure("SESSION_EXPIRED");currentCapture=new WindowsBrightnessSnapshot{Monitors=new ReadOnlyCollection<WindowsBrightnessMonitor>(monitors),CapturedUtc=captured,Owner=owner,WorkerSession=session,SessionToken=Text(data,"sessionToken"),ReadToken=Text(data,"readToken")};return currentCapture;}finally{gate.Release();}}
  public async Task<WindowsBrightnessOutcome> ApplyAsync(WindowsBrightnessSnapshot snapshot,WindowsBrightnessMonitor monitor,int value,Action demandPermission){if(demandPermission==null)throw new ArgumentNullException("demandPermission");if(!WritesAvailable)throw new WindowsBrightnessFailure("CONTROL_UNAVAILABLE");if(!IsCurrent(snapshot)||monitor==null||!snapshot.Monitors.Any(m=>Object.ReferenceEquals(m,monitor))||!monitor.SupportsWrite||!monitor.Levels.Contains(value))throw new WindowsBrightnessFailure("CAPTURE_EXPIRED");demandPermission();if(!await gate.WaitAsync(0))throw new WindowsBrightnessFailure("INTERFACE_BUSY");try{Action validate=()=>{demandPermission();if(!WritesAvailable)throw new WindowsBrightnessFailure("CONTROL_UNAVAILABLE");if(!IsCurrent(snapshot))throw new WindowsBrightnessFailure("CAPTURE_EXPIRED");};validate();var request=new Dictionary<string,object>{{"op","set"},{"targetId",monitor.Id},{"brightness",value},{"sessionToken",snapshot.SessionToken},{"readToken",snapshot.ReadToken},{"currentFingerprint",monitor.Fingerprint},{"experimental",true}};var reply=await backend.Request(request,snapshot.WorkerSession,validate);snapshot.Consumed=true;Successful(reply);if(disposed||!Object.ReferenceEquals(snapshot.WorkerSession,backend.SessionIdentity))throw new WindowsBrightnessFailure("SESSION_EXPIRED");var data=reply.data;bool? already=Flag(data,"alreadyCurrent"),attempted=Flag(data,"writeAttempted"),confirmed=Flag(data,"readbackConfirmed");int? original=Integer(Value(data,"originalBrightness"));uint? code=ReturnCode(Value(data,"methodReturnCode"));var observedRaw=Value(data,"observed");var observed=observedRaw==null?null:ParseMonitor(observedRaw as Dictionary<string,object>);string error=Text(data,"errorCode");if(Integer(Value(data,"schema"))!=1||!already.HasValue||!attempted.HasValue||!confirmed.HasValue||original!=monitor.CurrentBrightness||observed!=null&&(observed.Id!=monitor.Id||!observed.Levels.SequenceEqual(monitor.Levels))||error!=null&&!new[]{"METH