  public void Dispose(){disposed=true;if(currentCapture!=null)currentCapture.Consumed=true;currentCapture=null;backend.Dispose();}
 }
 public partial class MainWindow {
  WindowsBrightnessClient windowsBrightnessClient;WindowsBrightnessSnapshot windowsBrightness;WindowsBrightnessOutcome windowsBrightnessLastResult;Task windowsBrightnessTask;bool windowsBrightnessStopping;string windowsBrightnessMessage="";DispatcherTimer windowsBrightnessExpiryTimer;Func<DateTime> windowsBrightnessNow=()=>DateTime.UtcNow;
  readonly Dictionary<string,int> windowsBrightnessDraft=new Dictionary<string,int>(StringComparer.Ordinal);
  public bool WindowsBrightnessCanPreviewReload {get{return windowsBrightnessTask==null||windowsBrightnessTask.IsCompleted;}}
  void InitializeWindowsBrightness(){if(windowsBrightnessClient==null&&!windowsBrightnessStopping)windowsBrightnessClient=new WindowsBrightnessClient(new WindowsBrightnessWorkerBackend());if(!render&&!closing&&!windowsBrightnessStopping&&windowsBrightnessExpiryTimer==null){windowsBrightnessExpiryTimer=new DispatcherTimer(DispatcherPriority.Background){Interval=TimeSpan.FromSeconds(1)};windowsBrightnessExpiryTimer.Tick+=WindowsBrightnessExpiryTimerTick;windowsBrightnessExpiryTimer.Start();}}
  void WindowsBrightnessExpiryTimerTick(object sender,EventArgs args){WindowsBrightnessExpiryTick(windowsBrightnessNow());}
  void WindowsBrightnessExpiryTick(DateTime now){if(closing||windowsBrightnessStopping){StopWindowsBrightnessExpiry();return;}if(render||!IsLoaded||busy||AuraSyncBusy||page!="屏幕设置")return;if(ExpireWindowsBrightness(now))ShowPage(page);}
  bool ExpireWindowsBrightness(DateTime now){if(windowsBrightness==null)return false;if(windowsBrightnessClient!=null&&windowsBrightnessClient.IsCurrent(windowsBrightness)&&WindowsBrightnessRules.Current(windowsBrightness.CapturedUtc,now))return false;windowsBrightness.Consumed=true;windowsBrightness=null;windowsBrightnessDraft.Clear();windowsBrightnessMessage="请重新读取亮度。";return true;}
  void StopWindowsBrightnessExpiry(){if(windowsBrightnessExpiryTimer==null)return;windowsBrightnessExpiryTimer.Stop();windowsBrightnessExpiryTimer.Tick-=WindowsBrightnessExpiryTimerTick;windowsBrightnessExpiryTimer=null;}
  void AddWindowsBrightnessControls(){ExpireWindowsBrightness(windowsBrightnessNow());var box=Box("屏幕亮度","");var read=Button("读取亮度",async()=>await ReadWindowsBrightness());read.Tag="brightness-read";read.IsEnabled=!render&&!closing&&!busy&&!AuraSyncBusy&&!windowsBrightnessStopping;box.Children.Add(read);bool current=windowsBrightnessClient!=null&&windowsBrightnessClient.IsCurrent(windowsBrightness);if(!current){var state=Label("—",14,muted);state.ToolTip=windowsBrightness==null?"读取后显示系统支持的亮度控制。":"请重新读取亮度。";box.Children.Add(state);}else if(windowsBrightness.Monitors.Count==0)box.Children.Add(Label("系统未提供亮度控制",13,muted));else foreach(var monitor in windowsBrightness.Monitors){var row=new StackPanel{Tag="brightness-monitor:"+monitor.Id,Margin=new Thickness(0,14,0,4)};row.Children.Add(Label(monitor.Name,14,text));row.Children.Add(Label(monitor.CurrentBrightness.HasValue?monitor.CurrentBrightness+" %":"—",14,muted));int draft;if(!windowsBrightnessDraft.TryGetValue(monitor.Id,out draft)||!monitor.Levels.Contains(draft))draft=monitor.CurrentBrightness.HasValue?monitor.CurrentBrightness.Value:-1;var combo=MousePerformanceCombo(monitor.Levels.Select(v=>v+" %").ToArray(),draft>=0?monitor.Levels.IndexOf(draft):-1,monitor.SupportsWrite&&!busy&&!AuraSyncBusy,180);combo.Tag="brightness-level:"+monitor.Id;combo.Width=180;combo.HorizontalAlignment=HorizontalAlignment.Left;combo.IsEnabled=monitor.SupportsWrite&&!busy&&!AuraSyncBusy;combo.SelectionChanged+=(s,e)=>{if(!busy&&!AuraSyncBusy&&combo.SelectedIndex>=0&&combo.SelectedIndex<monitor.Levels.Count)windowsBrightnessDraft[monitor.Id]=monitor.Levels[combo.SelectedIndex];};row.Children.Add(combo);var captured=windowsBrightness;var target=monitor;var apply=Button("应用亮度",async()=>{int level;if(windowsBrightnessDraft.TryGetValue(target.Id,out level))await ApplyWindowsBrightness(captured,target,level);});apply.Tag="brightness-apply:"+monitor.Id;apply.IsEnabled=HardwareWritesEnabled&&!busy&&!AuraSyncBusy&&monitor.SupportsWrite&&windowsBrightnessClient.WritesAvailable;if(!windowsBrightnessClient.WritesAvailable){apply.ToolTip="上次亮度设置结果未确认，本次运行仅允许读取。";ToolTipService.SetShowOnDisabled(apply,true);}apply.HorizontalAlignment=HorizontalAlignment.Left;row.Children.Add(apply);windowsBrightnessDraft[monitor.Id]=draft;if(!monitor.SupportsWrite){var unavailable=Label("设置不可用",12,muted);unavailable.ToolTip="当前屏幕的亮度级别或设置接口未确认。";row.Children.Add(unavailable);}box.Children.Add(row);}if(!String.IsNullOrEmpty(windowsBrightnessMessage))box.Children.Add(Paragraph(windowsBrightnessMessage,12,muted));content.Children.Add(Card(box));}
  async Task ReadWindowsBrightness(){if(render||closing||busy||AuraSyncBusy||windowsBrightnessStopping)return;InitializeWindowsBrightness();busy=true;ShowPage(page);try{var task=windowsBrightnessClient.ReadAsync();windowsBrightnessTask=task;windowsSystemTask=task;var snapshot=await task;if(!closing&&!windowsBrightnessStopping){windowsBrightness=snapshot;windowsBrightnessDraft.Clear();windowsBrightnessLastResult=null;windowsBrightnessMessage="";}}catch(Exception){windowsBrightness=null;windowsBrightnessDraft.Clear();windowsBrightnessMessage="亮度读取未完成，请重新读取。";}finally{windowsBrightnessTask=null;windowsSystemTask=null;busy=false;if(!closing)ShowPage(page);}}
  async Task ApplyWindowsBrightness(WindowsBrightnessSnapshot snapshot,WindowsBrightnessMonitor monitor,int value){if(render||closing||busy||AuraSyncBusy||windowsBrightnessStopping||!Object.ReferenceEquals(snapshot,windowsBrightness)||windowsBrightnessClient==null)return;if(!PermitHardwareWrite())return;busy=true;windowsSystemWriting=true;ShowPage(page);try{Action demand=()=>{hardwareControlPolicy.Demand();if(render||closing||windowsBrightnessStopping||AuraSyncBusy||!Object.ReferenceEquals(snapshot,windowsBrightness))throw new WindowsBrightnessFailure("CONTROL_DISABLED");};var task=windowsBrightnessClient.ApplyAsync(snapshot,monitor,value,demand);windowsBrightnessTask=task;windowsSystemTask=task;var result=await task;if(!closing){windowsBrightnessLastResult=result;windowsBrightnessMessage=result.AlreadyCurrent?"亮度已相同，无需修改。":result.ReadbackConfirmed?"亮度已读回确认。":"亮度设置未确认，请重新读取。";}}catch(Exception){windowsBrightnessMessage="亮度设置未确认，请重新读取。";}finally{windowsBrightness=null;windowsBrightnessDraft.Clear();windowsBrightnessTask=null;windowsSystemTask=null;windowsSystemWriting=false;busy=false;if(!closing)ShowPage(page);}}
  async Task DisposeWindowsBrightnessAsync(){windowsBrightnessStopping=true;StopWindowsBrightnessExpiry();windowsBrightness=null;windowsBrightnessDraft.Clear();if(windowsBrightnessClient!=null)windowsBrightnessClient.Dispose();var task=windowsBrightnessTask;if(task!=null)try{await task;}catch(Exception){}windowsBrightnessClient=null;}
 }
